// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type MinimalCalendarProps = Record<string, any>;

const MinimalCalendar: React.FC<MinimalCalendarProps> = ({
  backgroundColor = "#2b2d31",
  transparentBackground = false,
  durationInSeconds = 10,
  cardColor = "#1c1d20",
  primaryTextColor = "#f2ead3",
  secondaryTextColor = "#a4947e",
  schedule = [
    { day: "Monday", activity: "Gym" },
    { day: "Tuesday", activity: "Practice\nGuitar" },
    { day: "Wednesday", activity: "Free Time" },
    { day: "Thursday", activity: "Family" },
    { day: "Friday", activity: "Practice\nGuitar" },
    { day: "Saturday", activity: "" },
    { day: "Sunday", activity: "" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Responsive layout calculations
  const containerWidth = width * 0.9;
  const gap = containerWidth * 0.012; // Gap between cards
  const totalGaps = (schedule.length - 1) * gap;
  const cardWidth = (containerWidth - totalGaps) / schedule.length;
  const cardHeight = height * 0.28;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: interFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: `${gap}px`,
          width: containerWidth,
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        {schedule.map((item, index) => {
          // Staggered calm animation
          const staggerDelay = index * 12; // frames between each card appearing
          
          const cardAppearance = spring({
            fps,
            frame: frame - staggerDelay,
            config: { damping: 24, stiffness: 50, mass: 1 }, // Gentle, non-bouncy spring
          });

          const opacity = interpolate(
            frame - staggerDelay,
            [0, 20],
            [0, 1],
            { extrapolateRight: "clamp" }
          );

          const translateY = interpolate(cardAppearance, [0, 1], [30, 0]);

          return (
            <div
              key={index}
              style={{
                width: cardWidth,
                height: cardHeight,
                backgroundColor: cardColor,
                borderRadius: height * 0.015,
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                paddingTop: height * 0.035,
                paddingBottom: height * 0.03,
                boxSizing: "border-box",
                opacity,
                transform: `translateY(${translateY}px)`,
                transition: "none",
                boxShadow: "0 4px 20px rgba(0,0,0,0.15)", // Subtle depth
              }}
            >
              {/* Day Label */}
              <span
                style={{
                  color: primaryTextColor,
                  fontSize: height * 0.032,
                  fontWeight: 400,
                  letterSpacing: "0.02em",
                  marginBottom: "auto", // Pushes activity label down
                  transition: "none",
                }}
              >
                {item.day}
              </span>

              {/* Activity Label */}
              <span
                style={{
                  color: secondaryTextColor,
                  fontSize: height * 0.028,
                  fontWeight: 400,
                  textAlign: "center",
                  lineHeight: 1.3,
                  whiteSpace: "pre-wrap", // Respects \n in defaults
                  marginTop: "auto", // Vertically centers in remaining space
                  marginBottom: height * 0.02,
                  transition: "none",
                }}
              >
                {item.activity}
              </span>
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default MinimalCalendar;